#
# One workflow, compiled: the resolved plan and the blocks' code. Assets:
#   __ME__/__WF__/<slot>/<source>/<step>   one per input step (LANDFIRE, wind, ...)
#   __ME__/__WF__/reference/<block>        the observed perimeter on the case grid
#   __ME__/__WF__/prediction               partitioned: one partition per run (model x params x inputs)
#   __ME__/__WF__/score/<metric>           partitioned like prediction
#   __ME__/__WF__/report                   every finished run's scores in one table
# Each step runs its block either in the blocks' image (IMAGE, a per-step image) or, if IMAGE
# is None, in the shared environment that <me>_bench_env_job builds. Either way it writes to
# the shared volume under the artifact's identity, so finished work is reused.
import base64
import json
import os
import shutil
import subprocess
import time
from pathlib import Path

import dagster as dg

ME = "__ME__"
WF = "__WF__"
ENV_ID = "__ENV_ID__"
IMAGE = __IMAGE__        # e.g. "docker.io/a3pearce/bench-blocks:<tag>"; None = shared environment
PLAN = json.loads(__PLAN__)
REFERENCE_GEOJSON = __REFERENCE__
CODE = {"core_blocks.py": __CORE_SOURCE__, "elmfire_block.py": __ELMFIRE_SOURCE__,
        "previews.py": __PREVIEW_SOURCE__}

STORE = Path(f"/opt/dagster/shared/storage/{ME}/bench")
ART = STORE / "artifacts"
GROUP = f"{ME}_{WF}"
RUN_KEYS = sorted(PLAN["runs"])
RUNS_PART = dg.StaticPartitionsDefinition(RUN_KEYS)
TAG_EMAIL = "bench/lfps_email"
MODEL_RESOURCES = {"requests": {"cpu": "2", "memory": "6Gi"}, "limits": {"cpu": "2.4", "memory": "7Gi"}}
BLOCK_RESOURCES = {"requests": {"cpu": "1", "memory": "3Gi"}, "limits": {"cpu": "1.2", "memory": "3600Mi"}}


def _k8s(resources: dict) -> dict:
    """op_tags for a block step: its resources and, if set, the blocks' image."""
    container = {"resources": resources, **({"image": IMAGE} if IMAGE else {})}
    return {"dagster-k8s/config": {"container_config": container}}


# --------------------------------------------------------------------------- #
# running a block in the shared environment
# --------------------------------------------------------------------------- #
def _env() -> tuple[str, dict]:
    """(python, environment variables) for running blocks."""
    code = Path("/tmp/bench/code")
    code.mkdir(parents=True, exist_ok=True)
    for name, text in CODE.items():
        (code / name).write_text(text)
    common = {"BENCH_ARTIFACT_ROOT": str(ART), "MPLCONFIGDIR": "/tmp/bench/mpl", "PYTHONUNBUFFERED": "1"}
    if IMAGE:   # the step already runs in the blocks' image: its own Python has every package
        import sys
        return sys.executable, {**os.environ, **common, "PYTHONPATH": str(code)}
    env = STORE / "env" / ENV_ID
    ready = env / "ready.json"
    if not ready.exists():
        raise dg.Failure(f"the blocks' environment {ENV_ID} isn't built yet: upload {ME}_bench_env.py "
                         f"and run {ME}_bench_env_job once")
    info = json.loads(ready.read_text())
    site = env / "site"
    variables = {**os.environ, **common, "PYTHONPATH": f"{site}:{code}", "LD_LIBRARY_PATH": f"{site}/bench_libs"}
    return str(env / info["python"]), variables


def _run_block(context, script: str, arg: Path, extra_env: dict | None = None) -> None:
    py, variables = _env()
    variables.update(extra_env or {})
    t = time.time()
    proc = subprocess.Popen([py, f"/tmp/bench/code/{script}", str(arg)], stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT, text=True, env=variables)
    tail = []
    for line in proc.stdout:
        line = line.rstrip()
        tail = (tail + [line])[-60:]
        if line and not line.startswith((" ", "{", "}", "]", "[")):
            context.log.info(f"[{script.split('_')[0]}] {line[:400]}")
    if proc.wait() != 0:
        raise dg.Failure(f"{script} failed after {time.time() - t:.0f}s", metadata={"output": "\n".join(tail)})


def _done(path: str) -> dict | None:
    marker = ART / path / "_done.json"
    return json.loads(marker.read_text()) if marker.exists() else None


def _materialize(context, path: str, build, reuse: bool = True) -> tuple[dict, bool]:
    """Build the artifact at its identity path unless it's already there.
    Built in a temporary sibling and renamed into place, so readers never see half an artifact."""
    if reuse and (done := _done(path)):
        context.log.info(f"reused {path} (finished {done.get('finished_utc')} by run {done.get('run_id', '?')[:8]})")
        return done, True
    final = ART / path
    tmp = ART / f"{path}.tmp-{context.run_id[:8]}"
    shutil.rmtree(tmp, ignore_errors=True)
    tmp.mkdir(parents=True)
    t = time.time()
    summary = build(tmp) or {}
    done = {"summary": summary, "seconds": round(time.time() - t, 1), "run_id": context.run_id,
            "finished_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}
    (tmp / "_done.json").write_text(json.dumps(done, default=str))
    if final.exists():
        shutil.rmtree(final)
    os.replace(tmp, final)
    return done, False


def _summary(tmp: Path) -> dict:
    prov = tmp / "provenance.json"
    return json.loads(prov.read_text()).get("summary", {}) if prov.exists() else {}


def _md_value(v):
    if isinstance(v, bool) or v is None:
        return str(v)
    if isinstance(v, (int, float)):
        return v
    return v if isinstance(v, str) and len(v) < 2000 else json.dumps(v, default=str)[:2000]


def _dry_run(tmp: Path, payload: dict, why: str) -> dict:   # TEMP(dry-run)
    (tmp / "provenance.json").write_text(json.dumps({"dry_run": True, "why": why, **payload}, default=str))
    return {"dry_run": True, "why": why}


# --------------------------------------------------------------------------- #
# input steps and the reference
# --------------------------------------------------------------------------- #
def _input_asset(entry: dict):
    @dg.asset(key=dg.AssetKey(entry["key"]), group_name=GROUP,
              deps=[dg.AssetKey(k) for k in entry["deps"]], code_version=entry["identity"],
              description=f"{entry['block']} ({entry['step']['kind']}): {entry['name']}",
              op_tags=_k8s(BLOCK_RESOURCES))
    def _a(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
        def build(tmp: Path):
            if not entry["real"]:
                return _dry_run(tmp, entry["step"], "no real implementation of this block yet")
            step = {**entry["step"], "out_dir": str(tmp),
                    "inputs": {k: str(ART / v) for k, v in entry["input_paths"].items()}}
            (tmp.parent / f"{tmp.name}.step.json").write_text(json.dumps(step))
            email = context.run.tags.get(TAG_EMAIL, "")
            _run_block(context, "core_blocks.py", tmp.parent / f"{tmp.name}.step.json",
                       {"BENCH_LFPS_EMAIL": email} if email else None)
            (tmp.parent / f"{tmp.name}.step.json").unlink()
            return _summary(tmp)
        done, reused = _materialize(context, entry["path"], build)
        return dg.MaterializeResult(metadata={
            **{k: _md_value(v) for k, v in done["summary"].items()},
            "reused": reused, "artifact": entry["path"], "identity": entry["identity"],
            "built_by_run": done.get("run_id", "")[:8], "build_s": done.get("seconds"),
            "dry_run": not entry["real"]})
    return _a


def _reference_asset(ref: dict):
    @dg.asset(key=dg.AssetKey(ref["key"]), group_name=GROUP, code_version=ref["identity"],
              description="The observed final perimeter, rasterized onto the case grid.",
              op_tags=_k8s(BLOCK_RESOURCES))
    def _r(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
        def build(tmp: Path):
            src = tmp / "_reference_source.geojson"
            src.write_text(REFERENCE_GEOJSON)
            step = {**ref["step"], "out_dir": str(tmp), "inputs": {"file": str(src)}}
            (tmp.parent / f"{tmp.name}.step.json").write_text(json.dumps(step))
            _run_block(context, "core_blocks.py", tmp.parent / f"{tmp.name}.step.json")
            (tmp.parent / f"{tmp.name}.step.json").unlink()
            return _summary(tmp)
        done, reused = _materialize(context, ref["path"], build)
        return dg.MaterializeResult(metadata={**{k: _md_value(v) for k, v in done["summary"].items()},
                                              "reused": reused, "artifact": ref["path"], "identity": ref["identity"],
                                              "built_by_run": done.get("run_id", "")[:8]})
    return _r


# --------------------------------------------------------------------------- #
# predictions (one partition per run), scores, report
# --------------------------------------------------------------------------- #
TAIL_KEYS = sorted({tuple(e["key"]) for e in PLAN["inputs"]
                    if not any(tuple(e["key"]) in [tuple(d) for d in o["deps"]] for o in PLAN["inputs"])})
PRED_KEY = dg.AssetKey([ME, WF, "prediction"])
REF_KEY = dg.AssetKey(PLAN["reference"]["key"]) if PLAN["reference"] else None


def _preview_md(pred_dir: Path) -> str | None:
    png = pred_dir / "preview.png"
    if not png.exists():
        return None
    return f"![prediction preview](data:image/png;base64,{base64.b64encode(png.read_bytes()).decode()})"


@dg.asset(key=PRED_KEY, group_name=GROUP, partitions_def=RUNS_PART, deps=[dg.AssetKey(list(k)) for k in TAIL_KEYS],
          description="One spread-model run per partition: model x params x input choices.",
          op_tags=_k8s(MODEL_RESOURCES))
def prediction(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
    run = PLAN["runs"][context.partition_key]
    missing = [s for s, p in run["input_paths"].items() if not _done(p)]
    if missing:
        raise dg.Failure(f"inputs not built yet for slots {missing}: run {ME}_{WF}_inputs_job first")

    def build(tmp: Path):
        if not run["real"]:
            return _dry_run(tmp, {"model": run["model"], "params": run["params"], "inputs": run["inputs"]},
                            f"{run['model']} has no real block yet")
        (tmp / "run.json").write_text(json.dumps(run["run_json"]))
        _run_block(context, "elmfire_block.py", tmp)
        pred = tmp / "prediction"
        # the framework's preview (same colours and scales for every model)
        py, variables = _env()
        r = subprocess.run([py, "-c", "import sys; from previews import render_prediction;"
                            "render_prediction(sys.argv[1], float(sys.argv[2]) or None)",
                            str(pred), str(run["params"].get("duration_min", 0) or 0)],
                           env=variables, capture_output=True, text=True)
        if r.returncode != 0:
            context.log.warning(f"preview failed (prediction kept): {r.stderr[-800:]}")
        return json.loads((pred / "summary.json").read_text())

    done, reused = _materialize(context, run["path"], build)
    md = {k: _md_value(v) for k, v in done["summary"].items()}
    preview = _preview_md(ART / run["path"] / "prediction")
    if preview:
        md["preview"] = dg.MetadataValue.md(preview)
    return dg.MaterializeResult(metadata={
        **md, "model": run["model"], "image": IMAGE or f"shared environment {ENV_ID}", "run_id": run["run_id"], "params": json.dumps(run["params"]),
        "inputs": json.dumps(run["inputs"] or {"(one source per slot)": "-"}),
        "reused": reused, "artifact": run["path"], "dry_run": not run["real"],
        "inputs_dry_run": ", ".join(s for s, r in run["input_real"].items() if not r) or "none"})


def _score_asset(metric: str):
    @dg.asset(key=dg.AssetKey([ME, WF, "score", metric]), group_name=GROUP, partitions_def=RUNS_PART,
              deps=[PRED_KEY] + ([REF_KEY] if REF_KEY else []),
              description=f"{metric}: prediction vs the observed perimeter.",
              op_tags=_k8s(BLOCK_RESOURCES))
    def _s(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
        run = PLAN["runs"][context.partition_key]
        if not run["real"]:
            return dg.MaterializeResult(metadata={"skipped": f"{run['model']} prediction is a dry run"})
        if not PLAN["reference"]:
            return dg.MaterializeResult(metadata={"skipped": "the workflow has no reference file yet"})
        for need, path in [("prediction", run["path"]), ("reference", PLAN["reference"]["path"])]:
            if not _done(path):
                raise dg.Failure(f"{need} not built yet ({path})")

        def build(tmp: Path):
            step = {"block": metric, "kind": "metric", "case": PLAN["case"], "params": {}, "out_dir": str(tmp),
                    "inputs": {"prediction": str(ART / run["path"] / "prediction"),
                               "reference": str(ART / PLAN["reference"]["path"])}}
            (tmp.parent / f"{tmp.name}.step.json").write_text(json.dumps(step))
            _run_block(context, "core_blocks.py", tmp.parent / f"{tmp.name}.step.json")
            (tmp.parent / f"{tmp.name}.step.json").unlink()
            return json.loads((tmp / "score.json").read_text())
        done, reused = _materialize(context, run["scores"][metric], build)
        return dg.MaterializeResult(metadata={**{k: _md_value(v) for k, v in done["summary"].items()},
                                              "reused": reused, "artifact": run["scores"][metric]})
    return _s


@dg.asset(key=dg.AssetKey([ME, WF, "report"]), group_name=GROUP,
          deps=[dg.AssetKey([ME, WF, "score", m]) for m in PLAN["metrics"]],
          description="Every finished run's scores in one table.")
def report(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
    rows = []
    for key in RUN_KEYS:
        run = PLAN["runs"][key]
        pred = _done(run["path"])
        row = {"run": key, "model": run["model"], "status": "not run" if not pred else
               ("dry run" if not run["real"] else "done")}
        if pred and run["real"]:
            row["predicted_ha"] = pred["summary"].get("burned_area_ha")
        for m in PLAN["metrics"]:
            s = _done(run.get("scores", {}).get(m, "-"))
            if s:
                row.update({k: v for k, v in s["summary"].items() if k in (m, "observed_ha")})
        rows.append(row)
    cols = []
    for r in rows:
        cols += [c for c in r if c not in cols]
    table = "| " + " | ".join(cols) + " |\n|" + "---|" * len(cols) + "\n" + "\n".join(
        "| " + " | ".join(str(r.get(c, "")) for c in cols) + " |" for r in rows)
    scored = [r for r in rows if "iou" in r]
    md = {"runs": len(rows), "scored": len(scored), "table": dg.MetadataValue.md(table),
          "rows": dg.MetadataValue.json(rows)}
    if scored:
        best = max(scored, key=lambda r: r["iou"])
        md.update({"best_run": best["run"], "best_iou": best["iou"]})
    return dg.MaterializeResult(metadata=md)


input_assets = [_input_asset(e) for e in PLAN["inputs"]]
ref_assets = [_reference_asset(PLAN["reference"])] if PLAN["reference"] else []
score_assets = [_score_asset(m) for m in PLAN["metrics"]]

defs = dg.Definitions(
    assets=[*input_assets, *ref_assets, prediction, *score_assets, report],
    jobs=[
        dg.define_asset_job(f"{ME}_{WF}_inputs_job",
                            selection=dg.AssetSelection.assets(*input_assets, *ref_assets)),
        dg.define_asset_job(f"{ME}_{WF}_runs_job", partitions_def=RUNS_PART,
                            selection=dg.AssetSelection.assets(prediction, *score_assets)),
        dg.define_asset_job(f"{ME}_{WF}_report_job", selection=dg.AssetSelection.assets(report)),
    ],
)
